const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Alisal Fire area in Santa Barbara County, CA (approximate location)
  const fireArea = ee.Geometry.Polygon([[
    [-120.3, 34.6],
    [-120.1, 34.6],
    [-120.1, 34.7],
    [-120.3, 34.7],
    [-120.3, 34.6]
  ]]);

  const startDate = '2021-10-11';
  const endDate = '2021-10-13';

  // 2. Data Acquisition - MODIS Burned Area
  const burnedAreaCol = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(fireArea);

  const colSize = burnedAreaCol.size().getInfo();
  console.log(`Burned area images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No burned area data found for the specified dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get burned area mask (BurnDate band > 0 indicates burned)
  const burnedAreaImg = burnedAreaCol.first();

  // Create burned area mask (pixels with BurnDate > 0)
  const burnedMask = burnedAreaImg.select('BurnDate').gt(0);

  // Calculate pixel count and area
  const pixelCount = burnedMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: fireArea,
    scale: 500,  // MCD64A1 resolution
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  console.log(`Burned pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No burned pixels detected in the area.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Convert to acres
  const pixelAreaSqM = 500 * 500;  // 500m resolution
  const totalAreaSqM = pixelCount * pixelAreaSqM;
  const totalAreaAcres = totalAreaSqM / 4046.86;  // Convert to acres

  console.log(`Total burned area: ${totalAreaAcres.toFixed(2)} acres`);

  // 5. Validation & Final Answer
  if (totalAreaAcres === null || isNaN(totalAreaAcres) || totalAreaAcres < 0) {
    console.log("Invalid area calculation.");
    console.log("<answer>C3</answer>");
  } else if (totalAreaAcres < 10000) {
    console.log("Burned area is less than 10,000 acres.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Burned area is 10,000 acres or more.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
